-- MPLAT-108 (D1 load): the badge counts and the Important list worked out "first message from this sender" with a
-- window function over every received message of the workspace on every poll (about 16.6k rows read per call on
-- mymail-au, plus a sort). The answer is now kept on the row: first_of_sender is 1 on the earliest message (by date,
-- then id) of each mailbox and lower(from_address), among messages not in Sent or Drafts. The same set the window
-- built, so Important counts and lists stay identical.
-- Triggers keep it, so every write path agrees (ingest, sync, imports, moves, deletes, repairs). Each trigger recomputes
-- the group's first from the source rows with one index seek (no +1/-1 arithmetic) and only writes a row whose flag
-- actually changes. Each trigger body is one statement (wrangler d1 migrations apply, as 0087). The bodies only set
-- first_of_sender, which no messages trigger listens to, so nothing fires twice.
ALTER TABLE `messages` ADD `first_of_sender` integer DEFAULT 0 NOT NULL;--> statement-breakpoint
-- The group lookup: earliest message of a mailbox and sender, outside Sent and Drafts.
CREATE INDEX `messages_sender_first_idx` ON `messages` (`mailbox_id`, lower(`from_address`), `date`, `id`) WHERE `folder` <> 'sent' AND `folder` <> 'drafts';--> statement-breakpoint
-- The flagged row of a group, so a trigger finds it without reading the group (one entry per mailbox and sender).
CREATE INDEX `messages_first_of_sender_idx` ON `messages` (`mailbox_id`, lower(`from_address`)) WHERE `first_of_sender` = 1;--> statement-breakpoint
-- Backfill: the same window the read used, once.
UPDATE `messages` SET `first_of_sender` = 1 WHERE `id` IN (SELECT f.`id` FROM (SELECT p.`id`, row_number() OVER (PARTITION BY p.`mailbox_id`, lower(p.`from_address`) ORDER BY p.`date`, p.`id`) AS rn FROM `messages` p WHERE p.`folder` <> 'sent' AND p.`folder` <> 'drafts') f WHERE f.rn = 1);--> statement-breakpoint
CREATE TRIGGER `messages_first_sender_ai_clear` AFTER INSERT ON `messages` WHEN NEW.`folder` <> 'sent' AND NEW.`folder` <> 'drafts' BEGIN UPDATE `messages` SET `first_of_sender` = 0 WHERE `mailbox_id` = NEW.`mailbox_id` AND lower(`from_address`) = lower(NEW.`from_address`) AND `first_of_sender` = 1 AND `id` IS NOT (SELECT p.`id` FROM `messages` p WHERE p.`mailbox_id` = NEW.`mailbox_id` AND lower(`from_address`) = lower(NEW.`from_address`) AND p.`folder` <> 'sent' AND p.`folder` <> 'drafts' ORDER BY p.`date`, p.`id` LIMIT 1); END;--> statement-breakpoint
CREATE TRIGGER `messages_first_sender_ai_set` AFTER INSERT ON `messages` WHEN NEW.`folder` <> 'sent' AND NEW.`folder` <> 'drafts' BEGIN UPDATE `messages` SET `first_of_sender` = 1 WHERE `id` = (SELECT p.`id` FROM `messages` p WHERE p.`mailbox_id` = NEW.`mailbox_id` AND lower(`from_address`) = lower(NEW.`from_address`) AND p.`folder` <> 'sent' AND p.`folder` <> 'drafts' ORDER BY p.`date`, p.`id` LIMIT 1) AND `first_of_sender` = 0; END;--> statement-breakpoint
CREATE TRIGGER `messages_first_sender_ad_set` AFTER DELETE ON `messages` WHEN OLD.`first_of_sender` = 1 BEGIN UPDATE `messages` SET `first_of_sender` = 1 WHERE `id` = (SELECT p.`id` FROM `messages` p WHERE p.`mailbox_id` = OLD.`mailbox_id` AND lower(`from_address`) = lower(OLD.`from_address`) AND p.`folder` <> 'sent' AND p.`folder` <> 'drafts' ORDER BY p.`date`, p.`id` LIMIT 1) AND `first_of_sender` = 0; END;--> statement-breakpoint
CREATE TRIGGER `messages_first_sender_au_old_clear` AFTER UPDATE OF `mailbox_id`, `from_address`, `date`, `folder` ON `messages` WHEN OLD.`mailbox_id` IS NOT NEW.`mailbox_id` OR lower(OLD.`from_address`) IS NOT lower(NEW.`from_address`) OR OLD.`date` IS NOT NEW.`date` OR (OLD.`folder` IN ('sent', 'drafts')) IS NOT (NEW.`folder` IN ('sent', 'drafts')) BEGIN UPDATE `messages` SET `first_of_sender` = 0 WHERE `mailbox_id` = OLD.`mailbox_id` AND lower(`from_address`) = lower(OLD.`from_address`) AND `first_of_sender` = 1 AND `id` IS NOT (SELECT p.`id` FROM `messages` p WHERE p.`mailbox_id` = OLD.`mailbox_id` AND lower(`from_address`) = lower(OLD.`from_address`) AND p.`folder` <> 'sent' AND p.`folder` <> 'drafts' ORDER BY p.`date`, p.`id` LIMIT 1); END;--> statement-breakpoint
CREATE TRIGGER `messages_first_sender_au_old_set` AFTER UPDATE OF `mailbox_id`, `from_address`, `date`, `folder` ON `messages` WHEN OLD.`mailbox_id` IS NOT NEW.`mailbox_id` OR lower(OLD.`from_address`) IS NOT lower(NEW.`from_address`) OR OLD.`date` IS NOT NEW.`date` OR (OLD.`folder` IN ('sent', 'drafts')) IS NOT (NEW.`folder` IN ('sent', 'drafts')) BEGIN UPDATE `messages` SET `first_of_sender` = 1 WHERE `id` = (SELECT p.`id` FROM `messages` p WHERE p.`mailbox_id` = OLD.`mailbox_id` AND lower(`from_address`) = lower(OLD.`from_address`) AND p.`folder` <> 'sent' AND p.`folder` <> 'drafts' ORDER BY p.`date`, p.`id` LIMIT 1) AND `first_of_sender` = 0; END;--> statement-breakpoint
CREATE TRIGGER `messages_first_sender_au_new_clear` AFTER UPDATE OF `mailbox_id`, `from_address`, `date`, `folder` ON `messages` WHEN OLD.`mailbox_id` IS NOT NEW.`mailbox_id` OR lower(OLD.`from_address`) IS NOT lower(NEW.`from_address`) OR OLD.`date` IS NOT NEW.`date` OR (OLD.`folder` IN ('sent', 'drafts')) IS NOT (NEW.`folder` IN ('sent', 'drafts')) BEGIN UPDATE `messages` SET `first_of_sender` = 0 WHERE `mailbox_id` = NEW.`mailbox_id` AND lower(`from_address`) = lower(NEW.`from_address`) AND `first_of_sender` = 1 AND `id` IS NOT (SELECT p.`id` FROM `messages` p WHERE p.`mailbox_id` = NEW.`mailbox_id` AND lower(`from_address`) = lower(NEW.`from_address`) AND p.`folder` <> 'sent' AND p.`folder` <> 'drafts' ORDER BY p.`date`, p.`id` LIMIT 1); END;--> statement-breakpoint
CREATE TRIGGER `messages_first_sender_au_new_set` AFTER UPDATE OF `mailbox_id`, `from_address`, `date`, `folder` ON `messages` WHEN OLD.`mailbox_id` IS NOT NEW.`mailbox_id` OR lower(OLD.`from_address`) IS NOT lower(NEW.`from_address`) OR OLD.`date` IS NOT NEW.`date` OR (OLD.`folder` IN ('sent', 'drafts')) IS NOT (NEW.`folder` IN ('sent', 'drafts')) BEGIN UPDATE `messages` SET `first_of_sender` = 1 WHERE `id` = (SELECT p.`id` FROM `messages` p WHERE p.`mailbox_id` = NEW.`mailbox_id` AND lower(`from_address`) = lower(NEW.`from_address`) AND p.`folder` <> 'sent' AND p.`folder` <> 'drafts' ORDER BY p.`date`, p.`id` LIMIT 1) AND `first_of_sender` = 0; END;--> statement-breakpoint
-- Saved contacts (not the automatic "mail" ones) for the Important rule: read only those, not every contact.
CREATE INDEX `contacts_org_kept_email_idx` ON `contacts` (`org_id`, lower(`email`)) WHERE `source` <> 'mail';
